create policy "product images read" on storage.objects for select to anon, authenticated using (bucket_id = 'products');
create policy "product images staff write" on storage.objects for insert to authenticated with check (bucket_id = 'products' and public.is_staff(auth.uid()));
create policy "product images staff delete" on storage.objects for delete to authenticated using (bucket_id = 'products' and public.is_staff(auth.uid()));